create schema private;

grant usage on schema private to authenticated;

create function private.is_friend(u1 uuid, u2 uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.friendships f
    where (f.requester_id = u1 and f.addressee_id = u2)
       or (f.requester_id = u2 and f.addressee_id = u1)
       and f.status = 'accepted'
  );
$$;

alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create policy friendships_select on public.friendships
  for select to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy friendships_insert on public.friendships
  for insert to authenticated
  with check (requester_id = auth.uid() and status = 'pending');

create policy friendships_update on public.friendships
  for update to authenticated
  using (status = 'pending' and addressee_id = auth.uid())
  with check (
    status in ('pending', 'accepted')
    and (requester_id <> addressee_id)
  );

create policy friendships_delete on public.friendships
  for delete to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy posts_select on public.posts
  for select to authenticated
  using (
    audience = 'public'
    or audience = 'friends'
    or author_id = auth.uid()
    or private.is_friend(auth.uid(), author_id)
  );

create policy posts_insert on public.posts
  for insert to authenticated
  with check (author_id = auth.uid());

create policy posts_update on public.posts
  for update to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

create policy posts_delete on public.posts
  for delete to authenticated
  using (author_id = auth.uid());

revoke all on public.friendships from anon, authenticated;
revoke all on public.posts from anon, authenticated;
revoke all on sequence public.posts_id_seq from anon, authenticated;

grant select, insert, update, delete on public.friendships to authenticated;
grant select, insert, update, delete on public.posts to authenticated;
grant usage, select on sequence public.posts_id_seq to authenticated;

grant all on public.friendships to service_role;
grant all on public.posts to service_role;
grant usage, select on sequence public.posts_id_seq to service_role;
