create or replace function public.is_auction_active(p_auction_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.ends_at > now()
  );
$$;

create or replace function public.is_auction_seller(p_auction_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.seller_id = auth.uid()
  );
$$;

create or replace function public.can_bid(p_auction_id bigint, p_amount numeric)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.ends_at > now()
      and (public.is_auction_seller(p_auction_id) or a.seller_id <> auth.uid())
  )
  and p_amount > 0
  and (
    (select coalesce(a.highest_bid, 0) from public.auctions a where a.id = p_auction_id) is null
    or p_amount > (
      select a.highest_bid + a.min_increment
      from public.auctions a
      where a.id = p_auction_id
    )
  );
$$;

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions%rowtype;
  v_highest numeric;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'invalid bid amount';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = auth.uid() then
    raise exception 'seller cannot bid on own auction';
  end if;

  if not public.can_bid(p_auction_id, p_amount) then
    raise exception 'bid amount is too low';
  end if;

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  return p_amount;
end;
$$;

