create or replace function public.is_auction_open(p_auction_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.ends_at > now()
  );
$$;

create or replace function public.bid_allowed(p_auction_id bigint, p_amount numeric)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_seller uuid;
  v_starting_price numeric;
  v_highest numeric;
  v_min_increment numeric;
  v_bidder uuid;
begin
  if p_amount is null then
    return false;
  end if;

  select a.seller_id, a.starting_price, a.highest_bid, a.min_increment, u.id
  into v_seller, v_starting_price, v_highest, v_min_increment, v_bidder
  from public.auctions a
           join auth.users u on u.id = auth.uid()
  where a.id = p_auction_id;

  if not found then
    return false;
  end if;

  if v_seller = v_bidder then
    return false;
  end if;

  if v_highest is null then
    return p_amount >= v_starting_price;
  end if;

  return p_amount >= v_highest + v_min_increment;
end;
$$;

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_seller uuid;
  v_starting_price numeric;
  v_highest numeric;
  v_min_increment numeric;
  v_bidder uuid := auth.uid();
  v_new_highest numeric;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not public.is_auction_open(p_auction_id) then
    raise exception 'auction is closed or does not exist';
  end if;

  select a.seller_id, a.starting_price, a.highest_bid, a.min_increment
  into v_seller, v_starting_price, v_highest, v_min_increment
  from public.auctions a
  where a.id = p_auction_id
  for update;

  if not found then
    raise exception 'auction does not exist';
  end if;

  if v_bidder is null then
    raise exception 'bidder identity not found';
  end if;

  if v_seller = v_bidder then
    raise exception 'seller cannot bid on own auction';
  end if;

  if v_highest is null then
    if p_amount < v_starting_price then
      raise exception 'bid below starting price';
    end if;
    v_new_highest := p_amount;
  else
    if p_amount < v_highest + v_min_increment then
      raise exception 'bid below minimum increment';
    end if;
    v_new_highest := p_amount;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_bidder, p_amount);

  update public.auctions
  set highest_bid = v_new_highest,
      highest_bidder = v_bidder
  where id = p_auction_id;

  return v_new_highest;
end;
$$;

