create or replace function public.class_spots_enforce_capacity()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.status = 'enrolled' then
    if exists (
      select 1
        from public.class_spots cs
       where cs.class_id = new.class_id
         and cs.user_id <> new.user_id
         and cs.status = 'enrolled'
    ) then
      if (select capacity from public.classes c where c.id = new.class_id) <= (
        select count(*)
          from public.class_spots cs
         where cs.class_id = new.class_id
           and cs.status = 'enrolled'
      ) then
        raise exception 'class is full';
      end if;
    end if;
  elsif new.status = 'waitlisted' then
    if exists (
      select 1
        from public.class_spots cs
       where cs.class_id = new.class_id
         and cs.user_id <> new.user_id
         and cs.status = 'enrolled'
    ) then
      if (select capacity from public.classes c where c.id = new.class_id) <= (
        select count(*)
          from public.class_spots cs
         where cs.class_id = new.class_id
           and cs.status in ('enrolled', 'waitlisted')
      ) then
        raise exception 'class is full';
      end if;
    end if;
  else
    raise exception 'invalid status';
  end if;

  return new;
end;
$$;

